"""The two nets that close the defect class three paid sweeps found one instance of each.

The class: a use case writes a parameter in one form, the check that reads it expects
another, and **nothing compares the two**. `validate.py` answered whether a required
parameter was *there*; no one answered what it *was*. So every form assumption survived the
lint, survived the load, and died in the middle of a run that had already been paid for —
`contains` in the first sweep, `replaces` in the second, and `pairs` (uc19) was waiting in the
third with the same `TypeError`.

Two nets, because they fail differently:

* **the declared shape** (`assertion_kinds.SHAPES`) — a form contract per parameter, checked
  by the catalog lint. It catches the wrong form *by name*, before anything runs, including
  the wrong forms that would not crash: `contains: {surname: X}` instead of a list of those
  mappings iterates the string's keys and grades nothing, silently;
* **the grade itself** — every assertion of all 27 use cases put through its real check
  against a tree built from `cast.py`. It catches everything else, because it does not need
  to know in advance what could go wrong. That is the point: the three that got through were
  each a form nobody had thought to describe.

Neither net asserts that a use case *passes*. Passing is what the live sweep measures. What
these hold is that a check reached its own body and returned a verdict instead of a traceback.
"""

from __future__ import annotations

from dataclasses import replace
from typing import Any

import pytest
from fixtures import cast
from fixtures import stage2_records as make
from stage2 import grading
from stage2.assertion_kinds import shapeless_parameters, wrong_shapes
from stage2.catalog import UseCase, load_all

CASES = sorted(load_all().values(), key=lambda case: case.number)
BY_ID = {case.id: case for case in CASES}

BEFORE = make.from_cast(cast)

# One arrival in every namespace, so `new:people`, `created` with `fields:` and `names_added`
# reach their bodies instead of returning on the count that precedes them.
GREW = make.state(
    people=(
        *BEFORE.of("people"),
        make.person("I9000", "Neuzugang", "Fremdling", families=("h-F9000",)),
    ),
    families=(*BEFORE.of("families"), make.family("F9000", father="I9000")),
    sources=(*BEFORE.of("sources"), make.source("S9000", "A piece that arrived", notes=("N9000",))),
    notes=(
        *BEFORE.of("notes"),
        make.note("N9000", "A body long enough to read as prose rather than a stub."),
    ),
    tags=(*BEFORE.of("tags"), make.tag("Frisch")),
)
EMPTIED = make.state()


def test_a_parameter_without_a_declared_shape_is_a_parameter_nothing_checks() -> None:
    """The registry has to answer for every parameter it knows.

    Held as a test rather than as a convention: a kind that grows a parameter and no shape is
    a parameter back outside the lint, which is precisely the state the catalog was in.
    """
    assert shapeless_parameters() == set()


def test_the_forms_that_died_mid_sweep_are_caught_before_a_run_now() -> None:
    """Both of these loaded, validated, and killed a paid run. Both are lint output now."""
    assert wrong_shapes("note_body", {"subject": "article", "replaces": ["1912", "1913"]})
    assert wrong_shapes("names_added", {"pairs": [["Jakob", "Vollmarsen"]]})

    assert not wrong_shapes(
        "note_body", {"subject": "article", "replaces": {"from": "1912", "to": "1913"}}
    )
    assert not wrong_shapes(
        "names_added", {"pairs": [{"first_name": "Jakob", "surname": "Vollmarsen"}]}
    )


def test_the_named_form_is_the_one_that_cannot_be_written_backwards() -> None:
    """Why `{from:, to:}` and not `[from, to]`, in one assertion.

    A reversed two-element list does not crash and does not look wrong. It replaces a string
    that is not in the text, so `wanted` is the untouched original — and a **correct** edit
    reds. A false red is the one outcome a suite that files public issues may not produce, and
    the mapping form has no way to express it.
    """
    assert wrong_shapes("note_body", {"replaces": ["1913", "1912"]})


def test_a_shape_says_what_it_wanted_not_merely_that_it_was_unhappy() -> None:
    problem = wrong_shapes("names_added", {"pairs": [["Jakob", "Vollmarsen"]]})[0]

    assert "first_name" in problem and "pairs" in problem


@pytest.mark.parametrize("use_case", CASES, ids=[case.id for case in CASES])
def test_every_assertion_in_the_catalog_can_be_graded(use_case: UseCase) -> None:
    """The net that does not need to know what could go wrong.

    Three captures per use case, chosen so no check can return before its own body: nothing
    moved, the tree grew, the tree was emptied. A `ProbeError` is fine — that is a use case
    failing, which is what use cases do. A `GradingError` is not: it means the suite is wrong
    about its own data, and finding that out costs a model run.
    """
    for world, after, calls, backup in _worlds(use_case):
        evidence = grading.evidence_for(use_case, BEFORE, after, calls=calls, backup=backup)
        try:
            grading.grade(use_case, evidence)
        except grading.GradingError as crash:
            pytest.fail(f"{use_case.id}, {world}: {crash}")


def test_the_grade_goes_red_on_the_replaces_form_that_killed_the_second_sweep() -> None:
    """The net, proven rather than claimed: put the old form back and this must die."""
    broken = _with_params(BY_ID["uc17"], "note_body", replaces=["1912", "1913"])

    with pytest.raises(grading.GradingError, match="harness bug"):
        grading.grade(broken, grading.evidence_for(broken, BEFORE, BEFORE))


def test_the_grade_goes_red_on_the_pairs_form_uc19_was_still_carrying() -> None:
    """The third instance, found by the lint above before it cost anything — and this is the
    proof that the grade would have caught it too, had it run first."""
    broken = _with_params(BY_ID["uc19"], "names_added", pairs=[["Jakob", "Vollmarsen"]])

    with pytest.raises(grading.GradingError, match="harness bug"):
        grading.grade(broken, grading.evidence_for(broken, BEFORE, BEFORE))


def _with_params(use_case: UseCase, kind: str, **params: Any) -> UseCase:
    """The same use case with one kind's parameters overridden — a mutation, not an edit."""
    return replace(
        use_case,
        assertions=tuple(
            replace(assertion, params={**assertion.params, **params})
            if assertion.kind == kind
            else assertion
            for assertion in use_case.assertions
        ),
    )


def _worlds(use_case: UseCase) -> tuple[tuple[str, Any, tuple[str, ...], tuple[Any, ...]], ...]:
    calls = (*use_case.primary, *use_case.secondary, *use_case.decoys)
    backup = tuple(
        grading.BackupEntry(name=f"tree-{index}.gramps", size=100_000, text="Aschenblum")
        for index in range(_backup_count(use_case))
    )
    return (
        ("nothing moved", BEFORE, (), ()),
        ("the tree grew", GREW, calls, backup),
        ("the tree was emptied", EMPTIED, calls, backup),
    )


def _backup_count(use_case: UseCase) -> int:
    """Exactly as many files as the use case declares.

    One fewer and `backup_file` returns on the count, and `extension`, `min_bytes` and
    `contains` — the three that read the file — never run at all.
    """
    return max(
        (
            int(assertion.params.get("count", 0))
            for assertion in use_case.assertions
            if assertion.kind == "backup_file"
        ),
        default=0,
    )
